import { User, Position } from "../../interfaces"
import PlayerApi from "../Api/Player"

interface Coordinates {
    /** Minimum X boundary of the zone */
    x1: number
    /** Maximum X boundary of the zone */
    x2: number
    /** Minimum Z boundary of the zone */
    z1: number
    /** Maximum Z boundary of the zone */
    z2: number
}

interface AddUserResult {
    /** Whether the user was successfully added to the floor */
    success: boolean
    /** Reason for failure, present only when `success` is `false` */
    reason?: "already_added" | "outside_floor"
}

/**
 * Represents a rectangular zone on a room's floor, used to detect
 * whether a given position falls within it.
 */
declare class Dimension {

    /**
     * Checks whether a position falls within this zone's bounds.
     * @param pos The position to check.
     */
    isInside(pos: Position): boolean
}

/**
 * A single dance floor zone. Tracks users currently inside it and
 * loops random emotes on each of them independently until they leave.
 */
declare class DanceFloor {

    /**
     * Adds a user to the floor and starts their random emote loop.
     * @param user The user to add.
     * @param position The user's current position, validated against the floor's bounds.
     */
    addUser(user: User, position: Position): Promise<AddUserResult>

    /**
     * Removes a user from the floor and stops their emote loop.
     * @param userId The unique identifier of the user to remove.
     * @returns `true` if the user was removed, `false` if they weren't tracked.
     */
    removeUser(userId: string): boolean

    /**
     * Checks whether a position falls within this floor's bounds.
     * @param pos The position to check.
     */
    isInside(pos: Position): boolean

    /**
     * Checks whether a user is currently tracked on this floor.
     * @param userId The unique identifier of the user.
     */
    hasUser(userId: string): boolean

    /**
     * Returns all users currently on this floor.
     */
    getUsers(): User[]

    /**
     * Stops every active emote loop on this floor and clears all tracked users.
     */
    destroy(): void
}

/**
 * Manages multiple dance floor zones within a room. Automatically detects
 * when users enter or leave a zone via movement updates, starting or
 * stopping their random emote loop accordingly.
 *
 * @example
 * ```js
 * const { DanceFloorsManager } = require("highrise.bot")
 * const danceFloors = new DanceFloorsManager(bot.player)
 * 
 * danceFloors.create("main", { x1: 0, x2: 10, z1: 0, z2: 10 })
 *
 * bot.on("Movement", async (user, position, anchor) => {
 *     await danceFloors.handleMovement(user, position)
 * })
 * ```
 */
declare class DanceFloorsManager {
    constructor(playerApi: PlayerApi)

    /**
     * Creates a new dance floor zone.
     * @param floorName Unique name identifying this floor.
     * @param coordinate The rectangular bounds of the zone.
     * @returns `true` if created, `false` if a floor with this name already exists.
     */
    create(floorName: string, coordinate: Coordinates): boolean

    /**
     * Removes a dance floor, stopping all active loops and clearing tracked users.
     * @param floorName The name of the floor to remove.
     * @returns `true` if removed, `false` if not found.
     */
    remove(floorName: string): boolean

    /**
     * Retrieves a specific dance floor by name.
     * @param floorName The name of the floor to retrieve.
     */
    get(floorName: string): DanceFloor | null

    /**
     * Returns the names of all registered dance floors.
     */
    getAll(): string[]

    /**
     * Determines whether a user has entered or left any dance floor zone
     * based on their current position, starting or stopping their emote
     * loop accordingly. Call this from your `Movement` event handler.
     * @param user The user who moved.
     * @param position The user's current position, or `null` if in a transitional state.
     */
    handleMovement(user: User, position: Position | null): Promise<void>

    /**
     * Stops all active loops across every dance floor and clears all state.
     */
    destroy(): void
}

export { DanceFloorsManager, DanceFloor, Dimension, Coordinates, AddUserResult }
export default DanceFloorsManager